 const filterButtons = document.querySelectorAll("[data-filter]");
 const productCards = document.querySelectorAll(".product-card");
 const filterStatus = document.querySelector("[data-filter-status]");
 const bagStatus = document.querySelector("[data-bag-status]");
 const addToBagButtons = document.querySelectorAll("[data-add-to-bag]");
 const bagCount = document.querySelector("[data-bag-count]");
 const bagButton = document.querySelector(".bag-button");

 let totalBagItems = 0;

 const setActiveFilter = (selectedButton) => {
   filterButtons.forEach((button) => {
     const isSelected = button === selectedButton;
     button.classList.toggle("is-active", isSelected);
     button.setAttribute("aria-pressed", String(isSelected));
   });
 };

 const updateProductVisibility = (filter) => {
   let visibleCount = 0;

   productCards.forEach((card) => {
     const shouldShow = filter === "all" || card.dataset.category === filter;
     card.hidden = !shouldShow;

     if (shouldShow) {
       visibleCount += 1;
     }
   });

   const filterLabel =
     filter === "all"
       ? "Showing all featured products."
       : `Showing ${visibleCount} ${filter} product${visibleCount === 1 ? "" : "s"}.`;

   filterStatus.textContent = filterLabel;
 };

 filterButtons.forEach((button) => {
   button.addEventListener("click", () => {
     setActiveFilter(button);
     updateProductVisibility(button.dataset.filter);
   });
 });

 addToBagButtons.forEach((button) => {
   button.addEventListener("click", () => {
     totalBagItems += 1;
     bagCount.textContent = String(totalBagItems);
     bagButton.setAttribute(
       "aria-label",
       `Shopping bag, ${totalBagItems} item${totalBagItems === 1 ? "" : "s"}`
     );
     bagStatus.textContent = `${button.dataset.addToBag} added to bag.`;
   });
 });

